class Warehouse extends DataClass implements Insertable<Warehouse> {
  /// Local UUID.
  final String id;

  /// UUID الخاص بالمخزن في الـBackend.
  final String? serverId;
  final String name;
  final String? code;

  /// Backend Branch UUID.
  final String? branchId;

  /// MAIN / SUB / VIRTUAL
  final String type;

  /// LOCAL / DRAFT / PENDING_APPROVAL / ACTIVE / ...
  final String status;

  /// Backend Warehouse UUID.
  /// يستخدم فقط إذا كان النوع SUB.
  final String? parentWarehouseId;

  /// Backend User UUID.
  final String? managerId;
  final String? address;
  final double? capacity;
  final String? notes;
  final String? rejectionReason;

  /// Compatibility مع الكود القديم.
  final bool isMain;
  final bool isActive;
  final int serverVersion;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime? deletedAt;
  const Warehouse({
    required this.id,
    this.serverId,
    required this.name,
    this.code,
    this.branchId,
    required this.type,
    required this.status,
    this.parentWarehouseId,
    this.managerId,
    this.address,
    this.capacity,
    this.notes,
    this.rejectionReason,
    required this.isMain,
    required this.isActive,
    required this.serverVersion,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    if (!nullToAbsent || serverId != null) {
      map['server_id'] = Variable<String>(serverId);
    }
    map['name'] = Variable<String>(name);
    if (!nullToAbsent || code != null) {
      map['code'] = Variable<String>(code);
    }
    if (!nullToAbsent || branchId != null) {
      map['branch_id'] = Variable<String>(branchId);
    }
    map['type'] = Variable<String>(type);
    map['status'] = Variable<String>(status);
    if (!nullToAbsent || parentWarehouseId != null) {
      map['parent_warehouse_id'] = Variable<String>(parentWarehouseId);
    }
    if (!nullToAbsent || managerId != null) {
      map['manager_id'] = Variable<String>(managerId);
    }
    if (!nullToAbsent || address != null) {
      map['address'] = Variable<String>(address);
    }
    if (!nullToAbsent || capacity != null) {
      map['capacity'] = Variable<double>(capacity);
    }
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    if (!nullToAbsent || rejectionReason != null) {
      map['rejection_reason'] = Variable<String>(rejectionReason);
    }
    map['is_main'] = Variable<bool>(isMain);
    map['is_active'] = Variable<bool>(isActive);
    map['server_version'] = Variable<int>(serverVersion);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    return map;
  }

