class Sale extends DataClass implements Insertable<Sale> {
  /// Local UUID.
  final String id;

  /// UUID الخاص بفاتورة Direct Sale في السيرفر.
  final String? serverId;
  final String invoiceNumber;

  /// Local Cashbox Session UUID.
  ///
  /// Nullable للمبيعات القديمة القادمة من قبل نظام الجلسات
  /// أو المبيعات التاريخية القادمة من السيرفر.
  final String? cashboxSessionId;

  /// Local Warehouse UUID.
  final String warehouseId;
  final String warehouseNameSnapshot;

  /// Local Customer UUID.
  final String? customerId;
  final String customerName;

  /// Local Representative UUID.
  ///
  /// حالياً Direct Sales API لا يحتوي representative_id،
  /// لذلك يبقى هذا الحقل محلياً لحين تأكيد عقد المندوب.
  final String? representativeId;
  final String? representativeNameSnapshot;
  final double? commissionPercentageSnapshot;
  final double commissionAmount;
  final double subtotal;
  final double discount;

  /// الحمالية على القائمة. تُضاف إلى الإجمالي ولا تُرسل للسيرفر.
  final double porterage;
  final double total;
  final double paidAmount;
  final double remainingAmount;

  /// CASH / CREDIT / PARTIAL.
  final String paymentType;

  /// IQD أو USD. المبالغ الأساسية تبقى بالدينار.
  final String currency;
  final double exchangeRate;
  final double totalUsd;
  final String notes;
  final int serverVersion;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime? deletedAt;
  const Sale({
    required this.id,
    this.serverId,
    required this.invoiceNumber,
    this.cashboxSessionId,
    required this.warehouseId,
    required this.warehouseNameSnapshot,
    this.customerId,
    required this.customerName,
    this.representativeId,
    this.representativeNameSnapshot,
    this.commissionPercentageSnapshot,
    required this.commissionAmount,
    required this.subtotal,
    required this.discount,
    required this.porterage,
    required this.total,
    required this.paidAmount,
    required this.remainingAmount,
    required this.paymentType,
    required this.currency,
    required this.exchangeRate,
    required this.totalUsd,
    required this.notes,
    required this.serverVersion,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    if (!nullToAbsent || serverId != null) {
      map['server_id'] = Variable<String>(serverId);
    }
    map['invoice_number'] = Variable<String>(invoiceNumber);
    if (!nullToAbsent || cashboxSessionId != null) {
      map['cashbox_session_id'] = Variable<String>(cashboxSessionId);
    }
    map['warehouse_id'] = Variable<String>(warehouseId);
    map['warehouse_name_snapshot'] = Variable<String>(warehouseNameSnapshot);
    if (!nullToAbsent || customerId != null) {
      map['customer_id'] = Variable<String>(customerId);
    }
    map['customer_name'] = Variable<String>(customerName);
    if (!nullToAbsent || representativeId != null) {
      map['representative_id'] = Variable<String>(representativeId);
    }
    if (!nullToAbsent || representativeNameSnapshot != null) {
      map['representative_name_snapshot'] = Variable<String>(
        representativeNameSnapshot,
      );
    }
    if (!nullToAbsent || commissionPercentageSnapshot != null) {
      map['commission_percentage_snapshot'] = Variable<double>(
        commissionPercentageSnapshot,
      );
    }
    map['commission_amount'] = Variable<double>(commissionAmount);
    map['subtotal'] = Variable<double>(subtotal);
    map['discount'] = Variable<double>(discount);
    map['porterage'] = Variable<double>(porterage);
    map['total'] = Variable<double>(total);
    map['paid_amount'] = Variable<double>(paidAmount);
    map['remaining_amount'] = Variable<double>(remainingAmount);
    map['payment_type'] = Variable<String>(paymentType);
    map['currency'] = Variable<String>(currency);
    map['exchange_rate'] = Variable<double>(exchangeRate);
    map['total_usd'] = Variable<double>(totalUsd);
    map['notes'] = Variable<String>(notes);
    map['server_version'] = Variable<int>(serverVersion);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    return map;
  }

  SalesCompanion toCompanion(bool nullToAbsent) {
    return SalesCompanion(
      id: Value(id),
      serverId: serverId == null && nullToAbsent
          ? const Value.absent()
          : Value(serverId),
      invoiceNumber: Value(invoiceNumber),
      cashboxSessionId: cashboxSessionId == null && nullToAbsent
          ? const Value.absent()
          : Value(cashboxSessionId),
      warehouseId: Value(warehouseId),
      warehouseNameSnapshot: Value(warehouseNameSnapshot),
      customerId: customerId == null && nullToAbsent
          ? const Value.absent()
          : Value(customerId),
      customerName: Value(customerName),
      representativeId: representativeId == null && nullToAbsent
          ? const Value.absent()
          : Value(representativeId),
      representativeNameSnapshot:
          representativeNameSnapshot == null && nullToAbsent
          ? const Value.absent()
          : Value(representativeNameSnapshot),
      commissionPercentageSnapshot:
          commissionPercentageSnapshot == null && nullToAbsent
          ? const Value.absent()
          : Value(commissionPercentageSnapshot),
      commissionAmount: Value(commissionAmount),
      subtotal: Value(subtotal),
      discount: Value(discount),
      porterage: Value(porterage),
      total: Value(total),
      paidAmount: Value(paidAmount),
      remainingAmount: Value(remainingAmount),
      paymentType: Value(paymentType),
      currency: Value(currency),
      exchangeRate: Value(exchangeRate),
      totalUsd: Value(totalUsd),
      notes: Value(notes),
      serverVersion: Value(serverVersion),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      deletedAt: deletedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(deletedAt),
    );
  }

