class SaleItem extends DataClass implements Insertable<SaleItem> {
  final String id;

  /// Local Sale UUID.
  final String saleId;

  /// Local Product UUID.
  final String productId;

  /// Local ProductVariant UUID.
  ///
  /// Nullable فقط لدعم البيانات القديمة.
  final String? variantId;

  /// Unit UUID.
  ///
  /// Units.id عندنا هو نفسه Server UUID.
  final String? unitId;
  final String productNameSnapshot;
  final String? barcodeSnapshot;

  /// COST / REP / WHOLESALE / RETAIL.
  final String priceType;
  final double quantity;

  /// كم قطعة داخل وحدة السطر. القطعة = 1، والكارتون = العدد الذي يحدده المستخدم.
  final double unitFactor;

  /// قطع مفردة تُباع مع الكارتون أو بدونه. الصفر مسموح.
  final int loosePieces;
  final double unitPrice;

  /// الخصم على مستوى السطر بالنسبة المئوية.
  final double discountPercent;
  final double total;
  final DateTime createdAt;
  const SaleItem({
    required this.id,
    required this.saleId,
    required this.productId,
    this.variantId,
    this.unitId,
    required this.productNameSnapshot,
    this.barcodeSnapshot,
    required this.priceType,
    required this.quantity,
    required this.unitFactor,
    required this.loosePieces,
    required this.unitPrice,
    required this.discountPercent,
    required this.total,
    required this.createdAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['sale_id'] = Variable<String>(saleId);
    map['product_id'] = Variable<String>(productId);
    if (!nullToAbsent || variantId != null) {
      map['variant_id'] = Variable<String>(variantId);
    }
    if (!nullToAbsent || unitId != null) {
      map['unit_id'] = Variable<String>(unitId);
    }
    map['product_name_snapshot'] = Variable<String>(productNameSnapshot);
    if (!nullToAbsent || barcodeSnapshot != null) {
      map['barcode_snapshot'] = Variable<String>(barcodeSnapshot);
    }
    map['price_type'] = Variable<String>(priceType);
    map['quantity'] = Variable<double>(quantity);
    map['unit_factor'] = Variable<double>(unitFactor);
    map['loose_pieces'] = Variable<int>(loosePieces);
    map['unit_price'] = Variable<double>(unitPrice);
    map['discount_percent'] = Variable<double>(discountPercent);
    map['total'] = Variable<double>(total);
    map['created_at'] = Variable<DateTime>(createdAt);
    return map;
  }

  SaleItemsCompanion toCompanion(bool nullToAbsent) {
    return SaleItemsCompanion(
      id: Value(id),
      saleId: Value(saleId),
      productId: Value(productId),
      variantId: variantId == null && nullToAbsent
          ? const Value.absent()
          : Value(variantId),
      unitId: unitId == null && nullToAbsent
          ? const Value.absent()
          : Value(unitId),
      productNameSnapshot: Value(productNameSnapshot),
      barcodeSnapshot: barcodeSnapshot == null && nullToAbsent
          ? const Value.absent()
          : Value(barcodeSnapshot),
      priceType: Value(priceType),
      quantity: Value(quantity),
      unitFactor: Value(unitFactor),
      loosePieces: Value(loosePieces),
      unitPrice: Value(unitPrice),
      discountPercent: Value(discountPercent),
      total: Value(total),
      createdAt: Value(createdAt),
    );
  }

  factory SaleItem.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return SaleItem(
      id: serializer.fromJson<String>(json['id']),
      saleId: serializer.fromJson<String>(json['saleId']),
      productId: serializer.fromJson<String>(json['productId']),
      variantId: serializer.fromJson<String?>(json['variantId']),
      unitId: serializer.fromJson<String?>(json['unitId']),
      productNameSnapshot: serializer.fromJson<String>(
        json['productNameSnapshot'],
      ),
      barcodeSnapshot: serializer.fromJson<String?>(json['barcodeSnapshot']),
      priceType: serializer.fromJson<String>(json['priceType']),
      quantity: serializer.fromJson<double>(json['quantity']),
      unitFactor: serializer.fromJson<double>(json['unitFactor']),
      loosePieces: serializer.fromJson<int>(json['loosePieces']),
      unitPrice: serializer.fromJson<double>(json['unitPrice']),
      discountPercent: serializer.fromJson<double>(json['discountPercent']),
      total: serializer.fromJson<double>(json['total']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'saleId': serializer.toJson<String>(saleId),
      'productId': serializer.toJson<String>(productId),
      'variantId': serializer.toJson<String?>(variantId),
      'unitId': serializer.toJson<String?>(unitId),
      'productNameSnapshot': serializer.toJson<String>(productNameSnapshot),
      'barcodeSnapshot': serializer.toJson<String?>(barcodeSnapshot),
      'priceType': serializer.toJson<String>(priceType),
      'quantity': serializer.toJson<double>(quantity),
      'unitFactor': serializer.toJson<double>(unitFactor),
      'loosePieces': serializer.toJson<int>(loosePieces),
      'unitPrice': serializer.toJson<double>(unitPrice),
      'discountPercent': serializer.toJson<double>(discountPercent),
      'total': serializer.toJson<double>(total),
      'createdAt': serializer.toJson<DateTime>(createdAt),
    };
  }

  SaleItem copyWith({
    String? id,
    String? saleId,
    String? productId,
    Value<String?> variantId = const Value.absent(),
    Value<String?> unitId = const Value.absent(),
    String? productNameSnapshot,
    Value<String?> barcodeSnapshot = const Value.absent(),
    String? priceType,
    double? quantity,
    double? unitFactor,
    int? loosePieces,
    double? unitPrice,
