          : this.productNameSnapshot,
      barcodeSnapshot: data.barcodeSnapshot.present
          ? data.barcodeSnapshot.value
          : this.barcodeSnapshot,
      priceType: data.priceType.present ? data.priceType.value : this.priceType,
      quantity: data.quantity.present ? data.quantity.value : this.quantity,
      unitFactor: data.unitFactor.present
          ? data.unitFactor.value
          : this.unitFactor,
      loosePieces: data.loosePieces.present
          ? data.loosePieces.value
          : this.loosePieces,
      unitPrice: data.unitPrice.present ? data.unitPrice.value : this.unitPrice,
      discountPercent: data.discountPercent.present
          ? data.discountPercent.value
          : this.discountPercent,
      total: data.total.present ? data.total.value : this.total,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
    );
  }

  @override
  String toString() {
    return (StringBuffer('SaleItem(')
          ..write('id: $id, ')
          ..write('saleId: $saleId, ')
          ..write('productId: $productId, ')
          ..write('variantId: $variantId, ')
          ..write('unitId: $unitId, ')
          ..write('productNameSnapshot: $productNameSnapshot, ')
          ..write('barcodeSnapshot: $barcodeSnapshot, ')
