class PurchaseItem extends DataClass implements Insertable<PurchaseItem> {
  final String id;
  final String purchaseId;

  /// Local Product UUID.
  final String productId;

  /// Local ProductVariant UUID.
  ///
  /// Nullable فقط لدعم البيانات القديمة قبل V15.
  /// كل فاتورة جديدة يجب أن تخزن variantId.
  final String? variantId;

  /// Unit UUID.
  ///
  /// Units.id عندنا هو نفسه Server UUID.
  /// Nullable لدعم البيانات القديمة.
  final String? unitId;
  final String productNameSnapshot;
  final String barcodeSnapshot;
  final int quantity;

  /// كم قطعة داخل وحدة السطر. القطعة = 1، والكارتون = العدد الذي يحدده المستخدم.
  final double unitFactor;
  final double unitCost;

  /// خصم على مستوى سطر الفاتورة بالنسبة المئوية.
  final double discountPercent;
  final DateTime createdAt;
  const PurchaseItem({
    required this.id,
    required this.purchaseId,
    required this.productId,
    this.variantId,
    this.unitId,
    required this.productNameSnapshot,
    required this.barcodeSnapshot,
    required this.quantity,
    required this.unitFactor,
    required this.unitCost,
    required this.discountPercent,
    required this.createdAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['purchase_id'] = Variable<String>(purchaseId);
    map['product_id'] = Variable<String>(productId);
    if (!nullToAbsent || variantId != null) {
      map['variant_id'] = Variable<String>(variantId);
    }
    if (!nullToAbsent || unitId != null) {
      map['unit_id'] = Variable<String>(unitId);
    }
    map['product_name_snapshot'] = Variable<String>(productNameSnapshot);
    map['barcode_snapshot'] = Variable<String>(barcodeSnapshot);
    map['quantity'] = Variable<int>(quantity);
    map['unit_factor'] = Variable<double>(unitFactor);
    map['unit_cost'] = Variable<double>(unitCost);
    map['discount_percent'] = Variable<double>(discountPercent);
    map['created_at'] = Variable<DateTime>(createdAt);
    return map;
  }

  PurchaseItemsCompanion toCompanion(bool nullToAbsent) {
    return PurchaseItemsCompanion(
      id: Value(id),
      purchaseId: Value(purchaseId),
      productId: Value(productId),
      variantId: variantId == null && nullToAbsent
          ? const Value.absent()
          : Value(variantId),
      unitId: unitId == null && nullToAbsent
          ? const Value.absent()
          : Value(unitId),
      productNameSnapshot: Value(productNameSnapshot),
      barcodeSnapshot: Value(barcodeSnapshot),
      quantity: Value(quantity),
      unitFactor: Value(unitFactor),
      unitCost: Value(unitCost),
      discountPercent: Value(discountPercent),
      createdAt: Value(createdAt),
    );
  }

  factory PurchaseItem.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return PurchaseItem(
      id: serializer.fromJson<String>(json['id']),
      purchaseId: serializer.fromJson<String>(json['purchaseId']),
      productId: serializer.fromJson<String>(json['productId']),
      variantId: serializer.fromJson<String?>(json['variantId']),
      unitId: serializer.fromJson<String?>(json['unitId']),
      productNameSnapshot: serializer.fromJson<String>(
        json['productNameSnapshot'],
      ),
      barcodeSnapshot: serializer.fromJson<String>(json['barcodeSnapshot']),
      quantity: serializer.fromJson<int>(json['quantity']),
      unitFactor: serializer.fromJson<double>(json['unitFactor']),
      unitCost: serializer.fromJson<double>(json['unitCost']),
      discountPercent: serializer.fromJson<double>(json['discountPercent']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'purchaseId': serializer.toJson<String>(purchaseId),
      'productId': serializer.toJson<String>(productId),
      'variantId': serializer.toJson<String?>(variantId),
      'unitId': serializer.toJson<String?>(unitId),
      'productNameSnapshot': serializer.toJson<String>(productNameSnapshot),
      'barcodeSnapshot': serializer.toJson<String>(barcodeSnapshot),
