      'unitFactor': serializer.toJson<double>(unitFactor),
      'unitCost': serializer.toJson<double>(unitCost),
      'discountPercent': serializer.toJson<double>(discountPercent),
      'createdAt': serializer.toJson<DateTime>(createdAt),
    };
