    unitId: unitId.present ? unitId.value : this.unitId,
    productNameSnapshot: productNameSnapshot ?? this.productNameSnapshot,
    barcodeSnapshot: barcodeSnapshot ?? this.barcodeSnapshot,
    quantity: quantity ?? this.quantity,
