class Representative extends DataClass implements Insertable<Representative> {
  final String id;
  final String? serverId;
  final String name;
  final String username;
  final String phone;
  final String officeName;
  final String officeAddress;
  final String officePhone;
  final String? locationLink;
  final double commissionPercentage;

  /// أسعار البيع المسموحة للمندوب، مفصولة بفاصلة.
  final String allowedPrices;
  final bool isActive;
  final int serverVersion;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime? deletedAt;
  const Representative({
    required this.id,
    this.serverId,
    required this.name,
    required this.username,
    required this.phone,
    required this.officeName,
    required this.officeAddress,
    required this.officePhone,
    this.locationLink,
    required this.commissionPercentage,
    required this.allowedPrices,
    required this.isActive,
    required this.serverVersion,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    if (!nullToAbsent || serverId != null) {
      map['server_id'] = Variable<String>(serverId);
    }
    map['name'] = Variable<String>(name);
    map['username'] = Variable<String>(username);
    map['phone'] = Variable<String>(phone);
    map['office_name'] = Variable<String>(officeName);
    map['office_address'] = Variable<String>(officeAddress);
    map['office_phone'] = Variable<String>(officePhone);
    if (!nullToAbsent || locationLink != null) {
      map['location_link'] = Variable<String>(locationLink);
    }
    map['commission_percentage'] = Variable<double>(commissionPercentage);
    map['allowed_prices'] = Variable<String>(allowedPrices);
    map['is_active'] = Variable<bool>(isActive);
    map['server_version'] = Variable<int>(serverVersion);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    return map;
  }

  RepresentativesCompanion toCompanion(bool nullToAbsent) {
    return RepresentativesCompanion(
      id: Value(id),
      serverId: serverId == null && nullToAbsent
          ? const Value.absent()
          : Value(serverId),
      name: Value(name),
      username: Value(username),
      phone: Value(phone),
      officeName: Value(officeName),
      officeAddress: Value(officeAddress),
      officePhone: Value(officePhone),
      locationLink: locationLink == null && nullToAbsent
          ? const Value.absent()
          : Value(locationLink),
      commissionPercentage: Value(commissionPercentage),
      allowedPrices: Value(allowedPrices),
      isActive: Value(isActive),
      serverVersion: Value(serverVersion),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      deletedAt: deletedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(deletedAt),
    );
  }

  factory Representative.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Representative(
      id: serializer.fromJson<String>(json['id']),
      serverId: serializer.fromJson<String?>(json['serverId']),
      name: serializer.fromJson<String>(json['name']),
      username: serializer.fromJson<String>(json['username']),
      phone: serializer.fromJson<String>(json['phone']),
      officeName: serializer.fromJson<String>(json['officeName']),
      officeAddress: serializer.fromJson<String>(json['officeAddress']),
      officePhone: serializer.fromJson<String>(json['officePhone']),
      locationLink: serializer.fromJson<String?>(json['locationLink']),
      commissionPercentage: serializer.fromJson<double>(
        json['commissionPercentage'],
      ),
      allowedPrices: serializer.fromJson<String>(json['allowedPrices']),
      isActive: serializer.fromJson<bool>(json['isActive']),
      serverVersion: serializer.fromJson<int>(json['serverVersion']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
      deletedAt: serializer.fromJson<DateTime?>(json['deletedAt']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'serverId': serializer.toJson<String?>(serverId),
      'name': serializer.toJson<String>(name),
      'username': serializer.toJson<String>(username),
      'phone': serializer.toJson<String>(phone),
      'officeName': serializer.toJson<String>(officeName),
      'officeAddress': serializer.toJson<String>(officeAddress),
      'officePhone': serializer.toJson<String>(officePhone),
      'locationLink': serializer.toJson<String?>(locationLink),
      'commissionPercentage': serializer.toJson<double>(commissionPercentage),
      'allowedPrices': serializer.toJson<String>(allowedPrices),
      'isActive': serializer.toJson<bool>(isActive),
      'serverVersion': serializer.toJson<int>(serverVersion),
      'createdAt': serializer.toJson<DateTime>(createdAt),
      'updatedAt': serializer.toJson<DateTime>(updatedAt),
      'deletedAt': serializer.toJson<DateTime?>(deletedAt),
    };
  }

  Representative copyWith({
    String? id,
    Value<String?> serverId = const Value.absent(),
    String? name,
    String? username,
    String? phone,
    String? officeName,
    String? officeAddress,
    String? officePhone,
    Value<String?> locationLink = const Value.absent(),
    double? commissionPercentage,
    String? allowedPrices,
