    username: username ?? this.username,
    phone: phone ?? this.phone,
    officeName: officeName ?? this.officeName,
    officeAddress: officeAddress ?? this.officeAddress,
    officePhone: officePhone ?? this.officePhone,
    locationLink: locationLink.present ? locationLink.value : this.locationLink,
    commissionPercentage: commissionPercentage ?? this.commissionPercentage,
    allowedPrices: allowedPrices ?? this.allowedPrices,
    isActive: isActive ?? this.isActive,
    serverVersion: serverVersion ?? this.serverVersion,
    createdAt: createdAt ?? this.createdAt,
    updatedAt: updatedAt ?? this.updatedAt,
    deletedAt: deletedAt.present ? deletedAt.value : this.deletedAt,
  );
  Representative copyWithCompanion(RepresentativesCompanion data) {
    return Representative(
      id: data.id.present ? data.id.value : this.id,
      serverId: data.serverId.present ? data.serverId.value : this.serverId,
      name: data.name.present ? data.name.value : this.name,
      username: data.username.present ? data.username.value : this.username,
      phone: data.phone.present ? data.phone.value : this.phone,
      officeName: data.officeName.present
          ? data.officeName.value
          : this.officeName,
      officeAddress: data.officeAddress.present
          ? data.officeAddress.value
          : this.officeAddress,
      officePhone: data.officePhone.present
          ? data.officePhone.value
          : this.officePhone,
      locationLink: data.locationLink.present
          ? data.locationLink.value
          : this.locationLink,
      commissionPercentage: data.commissionPercentage.present
          ? data.commissionPercentage.value
          : this.commissionPercentage,
      allowedPrices: data.allowedPrices.present
          ? data.allowedPrices.value
          : this.allowedPrices,
      isActive: data.isActive.present ? data.isActive.value : this.isActive,
      serverVersion: data.serverVersion.present
          ? data.serverVersion.value
          : this.serverVersion,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
      updatedAt: data.updatedAt.present ? data.updatedAt.value : this.updatedAt,
      deletedAt: data.deletedAt.present ? data.deletedAt.value : this.deletedAt,
    );
  }

  @override
  String toString() {
    return (StringBuffer('Representative(')
          ..write('id: $id, ')
          ..write('serverId: $serverId, ')
          ..write('name: $name, ')
          ..write('username: $username, ')
          ..write('phone: $phone, ')
          ..write('officeName: $officeName, ')
          ..write('officeAddress: $officeAddress, ')
          ..write('officePhone: $officePhone, ')
          ..write('locationLink: $locationLink, ')
          ..write('commissionPercentage: $commissionPercentage, ')
          ..write('allowedPrices: $allowedPrices, ')
          ..write('isActive: $isActive, ')
          ..write('serverVersion: $serverVersion, ')
          ..write('createdAt: $createdAt, ')
          ..write('updatedAt: $updatedAt, ')
          ..write('deletedAt: $deletedAt')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(
    id,
    serverId,
    name,
    username,
    phone,
    officeName,
    officeAddress,
    officePhone,
    locationLink,
    commissionPercentage,
    allowedPrices,
    isActive,
    serverVersion,
    createdAt,
    updatedAt,
    deletedAt,
  );
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is Representative &&
          other.id == this.id &&
          other.serverId == this.serverId &&
          other.name == this.name &&
          other.username == this.username &&
          other.phone == this.phone &&
          other.officeName == this.officeName &&
          other.officeAddress == this.officeAddress &&
          other.officePhone == this.officePhone &&
          other.locationLink == this.locationLink &&
          other.commissionPercentage == this.commissionPercentage &&
