    map['representative_id'] = Variable<String>(representativeId);
    map['method'] = Variable<String>(method);
    map['amount'] = Variable<double>(amount);
    if (!nullToAbsent || note != null) {
      map['note'] = Variable<String>(note);
    }
    if (!nullToAbsent || userId != null) {
      map['user_id'] = Variable<String>(userId);
    }
    map['server_version'] = Variable<int>(serverVersion);
    map['created_at'] = Variable<DateTime>(createdAt);
    return map;
  }

  RepresentativePaymentsCompanion toCompanion(bool nullToAbsent) {
    return RepresentativePaymentsCompanion(
      id: Value(id),
      voucherNumber: Value(voucherNumber),
      representativeId: Value(representativeId),
      method: Value(method),
      amount: Value(amount),
      note: note == null && nullToAbsent ? const Value.absent() : Value(note),
      userId: userId == null && nullToAbsent
          ? const Value.absent()
          : Value(userId),
      serverVersion: Value(serverVersion),
      createdAt: Value(createdAt),
    );
  }

  factory RepresentativePayment.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
