class CashboxSession extends DataClass implements Insertable<CashboxSession> {
  /// Local UUID.
  final String id;

  /// تاريخ العمل المحلي بصيغة YYYY-MM-DD.
  ///
  /// ملاحظة:
  /// لم يعد Unique لأن اليوم الواحد يمكن أن يحتوي
  /// على أكثر من جلسة صندوق.
  final String businessDate;

  /// الرصيد النقدي الموجود عند فتح هذه الجلسة.
  final double openingBalance;
  final double totalSales;
  final double cashSales;
  final double creditSales;
  final double partialSales;

  /// النقد المستلم فعلياً من فواتير البيع المرتبطة بهذه الجلسة.
  final double cashReceived;
  final double remainingAmount;
  final int invoicesCount;

  /// Opening Balance + Cash Received.
  ///
  /// لاحقاً يمكن توسيعها إلى:
  ///
  /// + Customer Receipts
  /// - Expenses
  /// - Supplier Payments
  /// - Refunds
  final double expectedCash;

  /// المبلغ الذي عده الموظف فعلياً عند الإغلاق.
  final double? countedCash;

  /// countedCash - expectedCash.
  final double? difference;

  /// OPEN / CLOSED.
  final String status;
  final String? note;
  final DateTime openedAt;
  final DateTime? closedAt;
  final DateTime createdAt;
  final DateTime updatedAt;
  const CashboxSession({
    required this.id,
    required this.businessDate,
    required this.openingBalance,
    required this.totalSales,
    required this.cashSales,
    required this.creditSales,
    required this.partialSales,
    required this.cashReceived,
    required this.remainingAmount,
    required this.invoicesCount,
    required this.expectedCash,
    this.countedCash,
    this.difference,
    required this.status,
    this.note,
    required this.openedAt,
    this.closedAt,
    required this.createdAt,
    required this.updatedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['business_date'] = Variable<String>(businessDate);
    map['opening_balance'] = Variable<double>(openingBalance);
    map['total_sales'] = Variable<double>(totalSales);
    map['cash_sales'] = Variable<double>(cashSales);
    map['credit_sales'] = Variable<double>(creditSales);
    map['partial_sales'] = Variable<double>(partialSales);
    map['cash_received'] = Variable<double>(cashReceived);
    map['remaining_amount'] = Variable<double>(remainingAmount);
    map['invoices_count'] = Variable<int>(invoicesCount);
    map['expected_cash'] = Variable<double>(expectedCash);
    if (!nullToAbsent || countedCash != null) {
      map['counted_cash'] = Variable<double>(countedCash);
    }
    if (!nullToAbsent || difference != null) {
      map['difference'] = Variable<double>(difference);
    }
    map['status'] = Variable<String>(status);
    if (!nullToAbsent || note != null) {
      map['note'] = Variable<String>(note);
    }
    map['opened_at'] = Variable<DateTime>(openedAt);
    if (!nullToAbsent || closedAt != null) {
      map['closed_at'] = Variable<DateTime>(closedAt);
    }
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    return map;
  }

  CashboxSessionsCompanion toCompanion(bool nullToAbsent) {
    return CashboxSessionsCompanion(
      id: Value(id),
      businessDate: Value(businessDate),
      openingBalance: Value(openingBalance),
      totalSales: Value(totalSales),
      cashSales: Value(cashSales),
      creditSales: Value(creditSales),
      partialSales: Value(partialSales),
      cashReceived: Value(cashReceived),
      remainingAmount: Value(remainingAmount),
      invoicesCount: Value(invoicesCount),
      expectedCash: Value(expectedCash),
      countedCash: countedCash == null && nullToAbsent
          ? const Value.absent()
          : Value(countedCash),
      difference: difference == null && nullToAbsent
          ? const Value.absent()
          : Value(difference),
      status: Value(status),
      note: note == null && nullToAbsent ? const Value.absent() : Value(note),
      openedAt: Value(openedAt),
      closedAt: closedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(closedAt),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
    );
  }

